# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÜLKEMİZİN TÜRK DÜNYASIYLA İŞ BİRLİĞİ KURULUŞLARI (SB.6.2.3)</text>\n  <rect x="18" y="46" width="212" height="196" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="124" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Siyasi ve Çatı Kuruluşlar</text>\n  <text x="30" y="92" font-size="11" font-weight="bold" fill="#1e40af">• TDT (Türk Devletleri Teşkilatı):</text>\n  <text x="30" y="108" font-size="10.5" fill="#334155">  2009 Nahçıvan Anlaşması ile kuruldu.</text>\n  <text x="30" y="123" font-size="10.5" fill="#334155">  Üyeler: Türkiye, Azerbaycan, Kazakistan,</text>\n  <text x="30" y="138" font-size="10.5" fill="#334155">  Kırgızistan, Özbekistan (Gözlemci:</text>\n  <text x="30" y="153" font-size="10.5" fill="#334155">  Türkmenistan, KKTC, Macaristan).</text>\n  <text x="30" y="175" font-size="11" font-weight="bold" fill="#1e40af">• TÜRKPA:</text>\n  <text x="30" y="191" font-size="10.5" fill="#334155">  Türk Devletleri Parlamenter Asamblesi</text>\n  <text x="124" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Dilde, Fikirde, İşte Birlik!</text>\n\n  <rect x="244" y="46" width="212" height="196" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Kültür ve Kalkınma</text>\n  <text x="256" y="92" font-size="11" font-weight="bold" fill="#166534">• TÜRKSOY (1993 - Ankara):</text>\n  <text x="256" y="108" font-size="10.5" fill="#334155">  Uluslararası Türk Kültürü Teşkilatı.</text>\n  <text x="256" y="123" font-size="10.5" fill="#334155">  Ortak kültür, sanat, Nevruz ve Türk</text>\n  <text x="256" y="138" font-size="10.5" fill="#334155">  Dünyası Kültür Başkenti etkinlikleri.</text>\n  <text x="256" y="162" font-size="11" font-weight="bold" fill="#166534">• TİKA (1992 - Ankara):</text>\n  <text x="256" y="178" font-size="10.5" fill="#334155">  Türk İşbirliği ve Koordinasyon Ajansı.</text>\n  <text x="256" y="193" font-size="10.5" fill="#334155">  Orhun Yazıtları yolu, Ahmet Yesevi</text>\n  <text x="256" y="208" font-size="10.5" fill="#334155">  Türbesi restorasyonu ve kalkınma.</text>\n\n  <rect x="470" y="46" width="212" height="196" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="576" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Eğitim ve Dil Kuruluşları</text>\n  <text x="482" y="92" font-size="11" font-weight="bold" fill="#854d0e">• Yunus Emre Enstitüsü (YEE):</text>\n  <text x="482" y="108" font-size="10.5" fill="#334155">  Türk dilini, edebiyatını ve kültürünü</text>\n  <text x="482" y="123" font-size="10.5" fill="#334155">  dünyada tanıtan kültür merkezleri.</text>\n  <text x="482" y="145" font-size="11" font-weight="bold" fill="#854d0e">• Türkiye Maarif Vakfı &amp; YTB:</text>\n  <text x="482" y="161" font-size="10.5" fill="#334155">  Yurt dışında okullar açar; Türkiye</text>\n  <text x="482" y="176" font-size="10.5" fill="#334155">  Bursları ile öğrenci değişimi sağlar.</text>\n  <text x="482" y="198" font-size="11" font-weight="bold" fill="#854d0e">• Türk Akademisi &amp; Ortak Alfabe:</text>\n  <text x="482" y="214" font-size="10.5" fill="#334155">  Ortak Türk tarihi ve 34 harfli alfabe.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TÜRKİSTAN\'DA KURULAN İLK TÜRK DEVLETLERİ VE YÖNETİM (SB.6.3.1)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">1. Asya Hun Devleti</text>\n  <text x="32" y="98" font-size="11" fill="#831843">• Tarihte bilinen ilk teşkilatlı</text>\n  <text x="32" y="114" font-size="11" fill="#831843">  Türk devletidir (Merkez: Ötüken).</text>\n  <text x="32" y="136" font-size="11" fill="#831843">• İlk hükümdar: Teoman</text>\n  <text x="32" y="154" font-size="11" fill="#831843">• En parlak dönem: Mete Han</text>\n  <text x="32" y="176" font-size="11" fill="#831843">• Orduda «Onlu Sistem»i kurdu.</text>\n  <text x="32" y="196" font-size="11" fill="#831843">• Oğuz Kağan Destanı\'na konu oldu.</text>\n  <text x="125" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Ordu-Millet ve Onlu Teşkilat</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">2. I. ve II. Kök Türk Devleti</text>\n  <text x="257" y="98" font-size="11" fill="#1e3a8a">• «Türk» adını siyasi devlet adı</text>\n  <text x="257" y="114" font-size="11" fill="#1e3a8a">  olarak kullanan ilk devlettir.</text>\n  <text x="257" y="136" font-size="11" fill="#1e3a8a">• I. Kök Türk: Bumin Kağan (552)</text>\n  <text x="257" y="154" font-size="11" fill="#1e3a8a">• II. Kök Türk (Kutluk): Kutluk</text>\n  <text x="257" y="172" font-size="11" fill="#1e3a8a">  Kağan, Bilge Kağan, Kültigin</text>\n  <text x="257" y="190" font-size="11" fill="#1e3a8a">  ve Vezir Tonyukuk.</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">38 Harfli Alfabe · Orhun Yazıtları</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">3. Uygur Devleti (744–840)</text>\n  <text x="482" y="98" font-size="11" fill="#14532d">• Kurucusu: Kutluk Bilge Kül Kağan</text>\n  <text x="482" y="116" font-size="11" fill="#14532d">• Bögü Kağan döneminde Maniheizm</text>\n  <text x="482" y="134" font-size="11" fill="#14532d">  inancını benimseyerek yerleşik</text>\n  <text x="482" y="152" font-size="11" fill="#14532d">  hayata geçen ilk Türk devletidir.</text>\n  <text x="482" y="174" font-size="11" fill="#14532d">• Şehirler (Balık), sulama kanalları,</text>\n  <text x="482" y="192" font-size="11" fill="#14532d">  18 harfli alfabe, kâğıt ve matbaa.</text>\n  <text x="575" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Yerleşik Yaşam, Tarım ve Matbaa</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İLK TÜRK DEVLETLERİNİN MEDENİYETİMİZE KATKILARI (SB.6.3.1)</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Devlet Yönetimi, Hukuk ve Bilim</text>\n  <text x="40" y="98" font-size="11.5" fill="#581c87">• Kut Anlayışı: Yönetme yetkisinin Gök</text>\n  <text x="40" y="116" font-size="11.5" fill="#581c87">  Tanrı tarafından verildiğine inanılması.</text>\n  <text x="40" y="138" font-size="11.5" fill="#581c87">• Töre: Herkesin (kağan dahil) uyduğu</text>\n  <text x="40" y="156" font-size="11.5" fill="#581c87">  yazısız hukuk ve toplumsal düzen kuralları.</text>\n  <text x="40" y="178" font-size="11.5" fill="#581c87">• Kurultay (Toy): Devlet işlerinin görüşüldüğü</text>\n  <text x="40" y="196" font-size="11.5" fill="#581c87">  danışma meclisi (Hatun da katılırdı).</text>\n  <text x="182" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Astronomi: 12 Hayvanlı Türk Takvimi</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Sanat, Ekonomi ve Yazılı Eserler</text>\n  <text x="375" y="98" font-size="11.5" fill="#155e75">• Pazırık Halısı: Dünyanın bilinen en eski</text>\n  <text x="375" y="116" font-size="11.5" fill="#155e75">  düğümlü halısı (dokumacılık kanıtı).</text>\n  <text x="375" y="138" font-size="11.5" fill="#155e75">• Altın Elbiseli Adam (Esik Kurganı):</text>\n  <text x="375" y="156" font-size="11.5" fill="#155e75">  Gelişmiş maden işçiliği ve hayvan üslubu.</text>\n  <text x="375" y="178" font-size="11.5" fill="#155e75">• Orhun Yazıtları: Bilge Kağan, Kültigin ve</text>\n  <text x="375" y="196" font-size="11.5" fill="#155e75">  Tonyukuk adına dikilen ilk yazılı belgeler.</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">İpek Yolu ve Kürk Yolu Ticaret Hâkimiyeti</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
